<style>
/* Ultra aggressive top space removal */
:root, html, body {
    margin: 0 !important;
    padding: 0 !important;
    top: 0 !important;
}
.admin-bar, .admin-bar html, .admin-bar body, .admin-bar #page {
    margin-top: 0 !important;
    padding-top: 0 !important;
}
#wpadminbar {
    display: none !important;
    height: 0 !important;
    opacity: 0 !important;
}
#page, .site, header, .site-header, .ranisahab-header, .rs-top-bar, #content, .site-content, #primary, .content-area, #main, .site-main {
    margin-top: 0 !important;
    padding-top: 0 !important;
    top: 0 !important;
}
/* Tighten gap under Hero Banner */
.sale-banner { margin-bottom: 0 !important; padding-bottom: 0 !important; }
.home-banner-new { padding-top: 30px !important; }
/* Premium Product Card Styling */
.owl-carousel-product .owl-item li, ul.products li.product {
    background: #fff;
    border-radius: 12px;
    box-shadow: 0 4px 15px rgba(0,0,0,0.04);
    transition: all 0.4s ease;
    border: 1px solid #f2f2f2;
    overflow: hidden;
    margin-bottom: 20px;
}
.owl-carousel-product .owl-item li:hover, ul.products li.product:hover {
    transform: translateY(-5px);
    box-shadow: 0 12px 25px rgba(183,28,28,0.08);
    border-color: #fce4e4;
}
.product-img { position: relative; overflow: hidden; border-bottom: 1px solid #f9f9f9; }
.product-img img { transition: transform 0.5s ease !important; width: 100%; display: block; }
.owl-carousel-product .owl-item li:hover .product-img img, ul.products li.product:hover .product-img img { transform: scale(1.08) !important; }
.cart-button { position: absolute; bottom: -60px; left: 0; width: 100%; transition: all 0.4s ease; opacity: 0; background: rgba(255,255,255,0.9); padding: 15px 10px; box-sizing: border-box; display: flex; justify-content: center; align-items: center; }
.owl-carousel-product .owl-item li:hover .cart-button, ul.products li.product:hover .cart-button { bottom: 0; opacity: 1; }
.cart-button-inner { width: 100%; }
.cart-button-inner a.button { display: block; text-align: center; background: #b71c1c !important; color: #fff !important; padding: 10px 15px; border-radius: 6px; font-weight: 600; font-size: 0.85rem; text-transform: uppercase; letter-spacing: 1px; transition: background 0.3s ease; text-decoration: none !important; width: 100%; box-sizing: border-box; }
.cart-button-inner a.button:hover { background: #8e1515 !important; }

.product-content { padding: 15px; text-align: center; }
.product-content a { color: #222; font-size: 0.95rem; font-weight: 600; text-decoration: none !important; display: block; margin-bottom: 8px; line-height: 1.4; transition: color 0.3s ease; }
.product-content a:hover { color: #b71c1c; }
.product-content .price { font-size: 1.1rem; color: #b71c1c; font-weight: 700; display: block; }
.product-content .price del, .product-content .price span.wcpbc-price > span:first-child { color: #999; font-size: 0.85rem; font-weight: 400; text-decoration: line-through; margin-right: 5px; display: inline-block; }
.rating-star { margin-bottom: 5px; color: #f39c12; font-size: 0.8rem; }
</style>
