<script>
    /* side menu */
    jQuery(document).ready(function ($) {
        function toggleSidebar() {
            $(".nav-button").toggleClass("active");
            $(".sidebar-item").toggleClass("active");
            $(".sidebar").toggleClass("active");
        }

        $(".nav-button").on("click tap", function () {
            toggleSidebar();
        });

        $(document).keyup(function (e) {
            if (e.keyCode === 27) {
                toggleSidebar();
            }
        });

    });

    /* on scroll add class */

    jQuery(document).ready(function ($) {
        $(window).scroll(function () {
            var scroll = $(window).scrollTop();
            var offset = 100; // Adjust this offset to the desired value

            if (scroll >= offset) {
                // When scrolled beyond the offset, add the class
                $('.site-header').addClass('active');
            } else {
                // Remove the class if the scroll is less than the offset
                $('.site-header').removeClass('active');
            }
        });
    });

</script>

<script>
    // JavaScript to handle showing buttons after successful addition to the cart
    document.addEventListener('DOMContentLoaded', function () {
        var addToCartButton = document.querySelector('.single_add_to_cart_button');
        var buyNowButton = document.querySelector('#direct_checkout');
        var successMessage = document.querySelector('.woocommerce-notices-wrapper .custom-woocommerce-message');

        if (successMessage && successMessage.textContent.includes('has been added to your basket')) {
            // Show view cart and checkout buttons
            var viewCartButtonContainer = document.getElementById('view-cart-button');
            var viewCheckoutButtonContainer = document.getElementById('view-checkout-button');
            // Hide add to cart button
            addToCartButton.style.display = 'none';
            buyNowButton.style.display = 'none';

            viewCartButtonContainer.style.display = 'inline-block';
            viewCheckoutButtonContainer.style.display = 'inline-block';
        }
    });
</script>

<script>
    document.addEventListener('DOMContentLoaded', function () {
    var couponToggleLink = document.querySelector('.woocommerce-form-coupon-toggle a.showcoupon');
    var couponForm = document.querySelector('.woocommerce-form-coupon');

    // Check if couponToggleLink exists
    if (couponToggleLink) {
        couponToggleLink.addEventListener('click', function (event) {
            event.preventDefault();
            toggleCouponForm();
        });
    }

    function toggleCouponForm() {
        if (couponForm.style.display === 'none') {
            couponForm.style.display = 'block';
        } else {
            couponForm.style.display = 'none';
        }
    }
});

/* == */
  document.addEventListener('DOMContentLoaded', function () {
    var shipToDifferentAddressCheckbox = document.getElementById('ship-to-different-address-checkbox');
    var shippingAddress = document.querySelector('.shipping_address');

    // Check if both elements exist
    if (shipToDifferentAddressCheckbox && shippingAddress) {
        // Initially hide the shipping address form
        shippingAddress.style.display = 'none';

        shipToDifferentAddressCheckbox.addEventListener('change', function () {
            if (this.checked) {
                shippingAddress.style.display = 'block';
            } else {
                shippingAddress.style.display = 'none';
            }
        });
    }
});

</script>


