        $('#size-chart-modal .close').on('click', function() {
            $('#size-chart-modal').hide();
        });



        $('.direct-checkout').on('click', function (e) {
            e.preventDefault();

            var $form = $(this).closest('form.variations_form');
            var allSelected = true;
            var missingAttrs = [];

            // Loop through each attribute group
            $form.find('.custom-variations tr').each(function () {
                var $attr = $(this);
                var attrName = $attr.find('input[type="radio"]').attr('name');

                if (attrName) {
                    var isChecked = $form.find('input[name="' + attrName + '"]:checked').length > 0;
                    if (!isChecked) {
                        allSelected = false;
                        missingAttrs.push(attrName.replace('attribute_pa_', '').replace(/_/g, ' '));
                    }
                }
            });

 

            if (!allSelected) {
                var alertMessage = '';
                var iconUrl = '';

                if (missingAttrs.includes('size')) {
                    alertMessage = 'Please select your Laddu Gopal deity size';
                    iconUrl = '/wp-content/themes/mahashringar/assets/images/diety-size.png';
                } 
                else if (missingAttrs.includes('color')) {
                    alertMessage = 'Please select track color';
                    // iconUrl = '/wp-content/themes/your-theme/assets/images/color-icon.png';
                } 
                else {
                    alertMessage = 'Please select: ' + missingAttrs.join(', ');
                    // iconUrl = '/wp-content/themes/your-theme/assets/images/warning.png';
                }

                customAlert(alertMessage, iconUrl);
                return;
            }


            // Check variation_id (final safety check)
            var variationId = $form.find('input.variation_id').val();
            if (!variationId || variationId === '0') {
                alert('Selected combination is not available.');
                return;
            }

            // Proceed to checkout
            var formData = $form.serialize();
            window.location.href = '#/checkout/?' + formData;
        });


        // Direct Checkout button click event for simple product
        $('.direct-checkout-simple').on('click', function (e) {
            e.preventDefault();
            var productId = $(this).prev('.single_add_to_cart_button').val();

            // Redirect to checkout page with the product ID
            window.location.href = '#/checkout/' + '?add-to-cart=' + productId;
        });
    });
</script>

