<script>
    // Get all elements and tooltips
    var elements = document.querySelectorAll(".element");
    var tooltips = document.querySelectorAll(".tooltip");

    // Loop through each element
    elements.forEach(function(element, index) {
      // Add event listener to show tooltip
      element.addEventListener("mouseover", function() {
        var rect = element.getBoundingClientRect();
        // Position tooltip relative to the element
        tooltips[index].style.top = rect.bottom + "px";
        tooltips[index].style.left = rect.left + "px";
        tooltips[index].style.display = "block";
      });
      
      // Add event listener to hide tooltip
      element.addEventListener("mouseout", function() {
        tooltips[index].style.display = "none";
      });
    });
</script>

<script>
    (function () {
        var measurementId = 'G-RGJWYZSD59';
        var analyticsLoaded = false;
        var loadingStarted = false;

        function initGtag() {
            if (analyticsLoaded) {
                return;
            }

            window.dataLayer = window.dataLayer || [];
            window.gtag = window.gtag || function () {
                dataLayer.push(arguments);
            };

            gtag('js', new Date());
            gtag('config', measurementId);
            analyticsLoaded = true;
        }

        function loadAnalyticsScript() {
            if (loadingStarted || analyticsLoaded) {
                return;
            }

            loadingStarted = true;
            var script = document.createElement('script');
            script.src = 'https://www.googletagmanager.com/gtag/js?id=' + measurementId;
            script.async = true;
            script.onload = initGtag;
            document.body.appendChild(script);
        }

        function bootstrapAnalytics() {
            loadAnalyticsScript();
            removeBootstrapListeners();
        }

        function removeBootstrapListeners() {
            ['scroll', 'mousemove', 'touchstart', 'click'].forEach(function (eventName) {
                document.removeEventListener(eventName, bootstrapAnalytics, { passive: true });
            });
        }

        ['scroll', 'mousemove', 'touchstart', 'click'].forEach(function (eventName) {
            document.addEventListener(eventName, bootstrapAnalytics, { passive: true });
        });

        // Fallback so analytics still loads for users who do not interact immediately.
        setTimeout(bootstrapAnalytics, 3000);
    })();
</script>

<script>
    (function () {
        var sessionKey = 'ms_traffic_event_sent';
        if (sessionStorage.getItem(sessionKey) === '1') {
            return;
        }

        var params = new URLSearchParams(window.location.search);
        var utmSource = (params.get('utm_source') || '').toLowerCase();
        var utmMedium = (params.get('utm_medium') || '').toLowerCase();
        var utmCampaign = (params.get('utm_campaign') || '').toLowerCase();
        var utmTerm = (params.get('utm_term') || '').toLowerCase();
        var utmContent = (params.get('utm_content') || '').toLowerCase();

        var clickIds = {
            gclid: params.get('gclid') || '',
            fbclid: params.get('fbclid') || '',
            ttclid: params.get('ttclid') || '',
            msclkid: params.get('msclkid') || ''
        };

        var referrerHost = '';
        try {
            referrerHost = document.referrer ? new URL(document.referrer).hostname.toLowerCase() : '';
        } catch (e) {
            referrerHost = '';
        }

        var socialDomains = ['facebook.com', 'instagram.com', 't.co', 'twitter.com', 'linkedin.com', 'youtube.com', 'pinterest.com'];
        var searchDomains = ['google.', 'bing.com', 'yahoo.com', 'duckduckgo.com'];

        function containsAny(value, list) {
            return list.some(function (item) {
                return value.indexOf(item) !== -1;
            });
        }

        function hasPaidSignals() {
            if (clickIds.gclid || clickIds.fbclid || clickIds.ttclid || clickIds.msclkid) {
                return true;
            }

            return /(cpc|ppc|paid|display|affiliate|retarget)/.test(utmMedium);
        }

        function classifySourceType() {
            if (hasPaidSignals()) {
                return 'ads';
            }

            if (/(social|social-organic|organic_social)/.test(utmMedium) || containsAny(utmSource, socialDomains) || containsAny(referrerHost, socialDomains)) {
                return 'social';
            }

            if (containsAny(referrerHost, searchDomains)) {
                return 'organic_search';
            }

            if (utmSource || utmMedium || utmCampaign) {
                return 'campaign';
            }

            if (referrerHost) {
                return 'referral';
            }

            return 'direct';
        }

        var sourceType = classifySourceType();

        function sendTrafficEvent() {
            if (typeof window.gtag !== 'function') {
                return false;
            }

            window.gtag('event', 'traffic_source_detected', {
                source_type: sourceType,
                utm_source: utmSource || '(none)',
                utm_medium: utmMedium || '(none)',
                utm_campaign: utmCampaign || '(none)',
                utm_term: utmTerm || '(none)',
                utm_content: utmContent || '(none)',
                referrer_host: referrerHost || '(direct)',
                click_id: clickIds.gclid ? 'gclid' : (clickIds.fbclid ? 'fbclid' : (clickIds.ttclid ? 'ttclid' : (clickIds.msclkid ? 'msclkid' : 'none'))),
                landing_path: window.location.pathname
            });

            sessionStorage.setItem(sessionKey, '1');
            return true;
        }

        var attempts = 0;
        var maxAttempts = 60;
        var retryDelay = 250;

        function waitAndSend() {
            attempts += 1;
            if (sendTrafficEvent() || attempts >= maxAttempts) {
                return;
            }

            setTimeout(waitAndSend, retryDelay);
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', waitAndSend);
            return;
        }

        waitAndSend();
    })();
</script>

<script>
document.addEventListener("DOMContentLoaded", function() {
    // Select all images in the document
    const images = document.querySelectorAll("img");

    images.forEach((img) => {
        // Check if the image has an alt attribute or if it's empty
        if (!img.hasAttribute("alt") || img.getAttribute("alt").trim() === "") {
            // Extract the filename from the src attribute
            const imageUrl = img.src;
            const imageName = imageUrl.substring(imageUrl.lastIndexOf("/") + 1);
            const altText = imageName.replace(/\.[^/.]+$/, "").replace(/-/g, " "); // Remove extension and replace hyphens with spaces

            console.log(altText);

            // Set the alt attribute
            img.setAttribute("alt", altText);
        }
    });
});

	// Wait for the DOM to be fully loaded
document.addEventListener("DOMContentLoaded", function() {
    // Function to add the woofc-show class to the body
    function addWoofcShowClassToBody() {
        document.body.classList.add("woofc-show");
    }

    // Attach click event listeners to Add to Cart buttons
    document.querySelectorAll('.add_to_cart_button, .single_add_to_cart_button').forEach(button => {
        button.addEventListener('click', function() {
            // Add the woofc-show class to the body
            addWoofcShowClassToBody();
        });
    });
});
</script>



